Literal.Value:
'{
  "$schema": "https://vega.github.io/schema/vega-lite/v6.json",
  "data": {
    "name": "dataset"
  },
  "height": 340,
  "encoding": {
    "x": {
      "field": "YearMonth",
      "type": "nominal",
      "sort": "ascending",
      "title": null,
      "scale": {
        "paddingInner": 0,
        "paddingOuter": 0.02
      },
      "axis": {
        "grid": false,
        "domain": false,
        "ticks": false,
        "labelAngle": 0,
        "labelPadding": 12,
        "labelFontSize": 12,
        "labelColor": "#475569",
        "labelFontWeight": 500,
        "labelExpr": "indexof([''01'',''07''], slice(datum.value,-2)) >= 0 ? ([''Ene'',''Feb'',''Mar'',''Abr'',''May'',''Jun'',''Jul'',''Ago'',''Sep'',''Oct'',''Nov'',''Dic''][+slice(datum.value,-2)-1] + '' '' + slice(datum.value,0,4)) : ''''"
      }
    }
  },
  "layer": [
    {
      "description": "Divisoria sutil en el cambio de año — detectada genéricamente (año de la fila != año de la fila anterior), no hardcodeada a 2024.",
      "transform": [
        {
          "filter": "isValid(datum.yearMonthPrev) && slice(datum.yearMonthPrev,0,4) != slice(datum[''YearMonth''],0,4)"
        }
      ],
      "mark": {
        "type": "rule",
        "strokeDash": [
          2,
          3
        ],
        "color": "#CBD5E1",
        "strokeWidth": 1
      },
      "encoding": {}
    },
    {
      "mark": {
        "type": "area",
        "interpolate": "monotone",
        "line": false,
        "color": {
          "gradient": "linear",
          "x1": 0,
          "y1": 1,
          "x2": 0,
          "y2": 0,
          "stops": [
            {
              "offset": 0,
              "color": "rgba(46,107,224,0)"
            },
            {
              "offset": 1,
              "color": "rgba(46,107,224,0.22)"
            }
          ]
        }
      },
      "encoding": {
        "y": {
          "field": "Total Sales",
          "type": "quantitative",
          "title": null,
          "scale": {
            "zero": false,
            "nice": true,
            "padding": 10
          },
          "axis": {
            "grid": true,
            "gridColor": "#E2E8F0",
            "gridDash": [
              2,
              2
            ],
            "format": "$.3~s",
            "labelColor": "#4B5563",
            "labelPadding": 8,
            "tickCount": 5
          },
          "stack": null
        }
      }
    },
    {
      "mark": {
        "type": "line",
        "interpolate": "monotone",
        "strokeWidth": 1.75,
        "strokeDash": [
          5,
          3
        ],
        "strokeCap": "round",
        "color": "#9AA5B1"
      },
      "encoding": {
        "y": {
          "field": "Sales PY",
          "type": "quantitative"
        }
      }
    },
    {
      "mark": {
        "type": "line",
        "interpolate": "monotone",
        "strokeWidth": 3,
        "strokeCap": "round",
        "strokeJoin": "round",
        "color": "#2E6BE0"
      },
      "encoding": {
        "y": {
          "field": "Total Sales",
          "type": "quantitative"
        }
      }
    },
    {
      "mark": {
        "type": "point",
        "filled": true,
        "size": 42,
        "color": "#2E6BE0",
        "stroke": "#FFFFFF",
        "strokeWidth": 1.5
      },
      "encoding": {
        "y": {
          "field": "Total Sales",
          "type": "quantitative"
        },
        "opacity": {
          "condition": {
            "test": "datum.__selected__ === ''off''",
            "value": 0.25
          },
          "value": 1
        },
        "tooltip": [
          {
            "field": "periodoLabel",
            "type": "nominal",
            "title": "Periodo"
          },
          {
            "field": "Total Sales",
            "type": "quantitative",
            "title": "Ventas",
            "format": "$,.0f"
          },
          {
            "field": "Sales PY",
            "type": "quantitative",
            "title": "Año anterior",
            "format": "$,.0f"
          }
        ]
      }
    },
    {
      "transform": [
        {
          "filter": "datum.ordenReciente === 1"
        }
      ],
      "mark": {
        "type": "point",
        "filled": true,
        "size": 130,
        "color": "#2E6BE0",
        "stroke": "#FFFFFF",
        "strokeWidth": 2.5
      },
      "encoding": {
        "y": {
          "field": "Total Sales",
          "type": "quantitative"
        }
      }
    },
    {
      "transform": [
        {
          "filter": "datum.ordenReciente === 1"
        }
      ],
      "mark": {
        "type": "text",
        "align": "right",
        "dx": -8,
        "dy": 20,
        "fontSize": 12.5,
        "fontWeight": 600,
        "color": "#0F172A"
      },
      "encoding": {
        "y": {
          "field": "Total Sales",
          "type": "quantitative"
        },
        "text": {
          "value": {
            "expr": "datum.periodoLabel + '' · '' + format(datum[''Total Sales''], ''$,.3~s'')"
          }
        }
      }
    },
    {
      "transform": [
        {
          "filter": "datum.ordenReciente === 1"
        },
        {
          "filter": "isValid(datum.yoy)"
        }
      ],
      "mark": {
        "type": "text",
        "align": "right",
        "dx": -8,
        "dy": 36,
        "fontSize": 11,
        "fontWeight": 600
      },
      "encoding": {
        "y": {
          "field": "Total Sales",
          "type": "quantitative"
        },
        "text": {
          "value": {
            "expr": "(datum.yoy >= 0 ? ''+'' : '''') + format(datum.yoy, ''.1%'') + '' interanual''"
          }
        },
        "color": {
          "condition": {
            "test": "datum.yoy >= 0",
            "value": "#0F766E"
          },
          "value": "#BE123C"
        }
      }
    }
  ],
  "transform": [
    {
      "calculate": "[''Enero'',''Febrero'',''Marzo'',''Abril'',''Mayo'',''Junio'',''Julio'',''Agosto'',''Septiembre'',''Octubre'',''Noviembre'',''Diciembre''][+slice(datum[''YearMonth''],-2)-1] + '' '' + slice(datum[''YearMonth''],0,4)",
      "as": "periodoLabel"
    },
    {
      "calculate": "isValid(datum[''Sales PY'']) ? (datum[''Total Sales''] - datum[''Sales PY'']) / datum[''Sales PY''] : null",
      "as": "yoy"
    },
    {
      "window": [
        {
          "op": "row_number",
          "as": "ordenReciente"
        }
      ],
      "sort": [
        {
          "field": "YearMonth",
          "order": "descending"
        }
      ]
    },
    {
      "window": [
        {
          "op": "lag",
          "field": "YearMonth",
          "as": "yearMonthPrev"
        }
      ]
    }
  ],
  "config": {
    "background": "transparent",
    "font": "Segoe UI",
    "view": {
      "stroke": "transparent"
    },
    "axis": {
      "grid": false,
      "domain": false,
      "ticks": false,
      "labelColor": "#4B5563",
      "labelFontSize": 12,
      "titleColor": "#0F172A",
      "titleFontWeight": "normal"
    },
    "text": {
      "font": "Segoe UI"
    }
  },
  "title": {
    "text": "Ventas, mes a mes · 2023–2024",
    "subtitle": [
      "Línea sólida: año en curso · línea punteada: mismo mes, año anterior",
      "Contoso Retail · haz clic en un mes para filtrar el resto del informe"
    ],
    "anchor": "start",
    "font": "Segoe UI",
    "fontSize": 19,
    "fontWeight": 600,
    "color": "#0F172A",
    "subtitleFont": "Segoe UI",
    "subtitleFontSize": 12,
    "subtitleFontWeight": "normal",
    "subtitleColor": "#5B6675",
    "subtitleLineHeight": 17,
    "subtitlePadding": 10,
    "offset": 18
  },
  "padding": {
    "left": 4,
    "top": 4,
    "bottom": 4,
    "right": 16
  }
}'
